import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import { StarFill, Star } from 'react-bootstrap-icons';

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [rating, setRating] = useState(0);
  const [hover, setHover] = useState(0);
  const [comment, setComment] = useState("");
  const [showCommentForm, setShowCommentForm] = useState(false);
  const [userComments, setUserComments] = useState([
    {
      name: "Lucas Pedro",
      text: "Conteúdo excelente e plataforma super intuitiva! Aprender aqui é um prazer.",
      rating: 5
    },
    {
      name: "Rafael Santos",
      text: "EducaWeb me ajudou a crescer profissionalmente. Recomendo a todos!",
      rating: 5
    }
  ]);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCursos = async () => {
      try {
        const response = await axios.get("http://localhost:5000/cursos");
        setCursos(response.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    // Verificar autenticação
    const checkAuth = () => {
      const token = localStorage.getItem("token");
      if (token) {
        setIsAuthenticated(true);
      }
    };

    fetchCursos();
    checkAuth();
  }, []);

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", { state: { from: path } });
    }
  };

  const handleCommentSubmit = (e) => {
    e.preventDefault();
    if (!isAuthenticated) {
      navigate('/login', { state: { from: '/', action: 'comment' } });
      return;
    }

    // Aqui você faria a chamada à API para salvar o comentário
    const newComment = {
      name: "Novo Usuário", // Substituir pelo nome do usuário logado
      text: comment,
      rating: rating
    };

    setUserComments([...userComments, newComment]);
    setComment("");
    setRating(0);
    setShowCommentForm(false);
  };

  // Agrupa cursos por área
  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="alert alert-danger">
          Erro ao carregar cursos: {error}
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid"
      style={{
        backgroundColor: "#F8F9FA",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="d-flex justify-content-end p-3">
        <a href="." className="mx-2">
          Home
        </a>
        <a href="./about" className="mx-2">
          About
        </a>
        <a href="./faq" className="mx-2">
          Faq
        </a>
        <a href="./contact" className="mx-2">
          Contacto
        </a>
        <a href="./login" className="mx-2">
          Login
        </a>
        <a href="./register" className="mx-2">
          Registo
        </a>
      </nav>
      <h1>EducaWeb</h1>

      {/* Seção de Cursos */}
      <div className="row mt-4">
        {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
          <div className="col-md-6 mb-4" key={area}>
            <div className="card h-100">
              <div className="card-body">
                <h2 className="card-title">
                  {area} {getEmojiForArea(area)}
                </h2>
                <ul className="list-group list-group-flush">
                  {cursosDaArea.map((curso) => (
                    <li className="list-group-item" key={curso.id}>
                      <strong>{curso.nome}</strong>
                      <div className="text-muted small mt-1">
                        {curso.periodo} | Nível {curso.nivel}
                      </div>
                      <div className="text-muted small">
                        {formatDate(curso.dataInicio)} -{" "}
                        {formatDate(curso.dataFim)}
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Restante do seu conteúdo */}
      <div className="row mt-5">
        <div className="col-md-6 bg-white p-4 rounded shadow">
          <h3 className="mb-4">Avaliações dos Usuários</h3>
          
          {userComments.map((comment, index) => (
            <div key={index} className="mb-4">
              <div className="d-flex align-items-center mb-2">
                <h5 className="mb-0">{comment.name}</h5>
                <div className="ms-3">
                  {[...Array(5)].map((_, i) => (
                    i < comment.rating ? 
                    <StarFill key={i} color="#ffc107" className="me-1" /> : 
                    <Star key={i} color="#ffc107" className="me-1" />
                  ))}
                </div>
              </div>
              <p className="mb-0">{comment.text}</p>
            </div>
          ))}

          {isAuthenticated ? (
            showCommentForm ? (
              <form onSubmit={handleCommentSubmit}>
                <div className="mb-3">
                  <label className="form-label">Sua avaliação</label>
                  <div className="d-flex mb-2">
                    {[...Array(5)].map((_, i) => (
                      <span 
                        key={i}
                        onMouseEnter={() => setHover(i + 1)}
                        onMouseLeave={() => setHover(0)}
                        onClick={() => setRating(i + 1)}
                        style={{ cursor: 'pointer' }}
                      >
                        {i < (hover || rating) ? 
                          <StarFill color="#ffc107" size={24} className="me-1" /> : 
                          <Star color="#ffc107" size={24} className="me-1" />}
                      </span>
                    ))}
                  </div>
                  <textarea
                    className="form-control"
                    rows="3"
                    value={comment}
                    onChange={(e) => setComment(e.target.value)}
                    placeholder="Escreva seu comentário..."
                    required
                  />
                </div>
                <div className="d-flex justify-content-end">
                  <button 
                    type="button" 
                    className="btn btn-outline-secondary me-2"
                    onClick={() => setShowCommentForm(false)}
                  >
                    Cancelar
                  </button>
                  <button type="submit" className="btn btn-primary">
                    Enviar Avaliação
                  </button>
                </div>
              </form>
            ) : (
              <button 
                className="btn btn-outline-primary"
                onClick={() => setShowCommentForm(true)}
              >
                Deixar uma Avaliação
              </button>
            )
          ) : (
            <div className="alert alert-info">
              <p className="mb-2">Faça login para deixar sua avaliação</p>
              <button 
                className="btn btn-sm btn-primary"
                onClick={() => navigate('/login')}
              >
                Fazer Login
              </button>
            </div>
          )}
        </div>

        <div className="col-md-6 bg-white p-4 rounded shadow">
          <div className="list-group">
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => navigate("/cursos")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📦 Cursos
            </button>

            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-ao-vivo")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📚 Aulas ao Vivo
            </button>

            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-gravadas")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📺 Aulas Gravadas
            </button>

            <button
              className="list-group-item list-group-item-action border-0 text-start p-0"
              onClick={() => handleProtectedLink("/material")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📂 Material de Apoio
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// Funções auxiliares
function getEmojiForArea(area) {
  const emojis = {
    Economia: "📉",
    Programação: "💻",
    Contabilidade: "📊",
    Inglês: "📖",
    Matemática: "🧮",
    Design: "🎨",
  };
  return emojis[area] || "📚";
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
